package org.example.Employee;public class Employee {    private int id;    private String name;    private Salary salary;    private Address address;    private Department department;    public Employee(int id, String name,                    Salary salary,                    Address address,                    Department department) {        this.id = id;        this.name = name;        this.salary = salary;        this.address = address;        this.department = department;    }    public void display() {        System.out.println("===== Employee Details =====");        System.out.println("Employee ID: " + id);        System.out.println("Employee Name: " + name);        System.out.println("Department ID: "                + department.getDepartmentId());        System.out.println("Department: "                + department.getDepartmentName());        System.out.println("City: " + address.getCity());        System.out.println("State: " + address.getState());        System.out.println("Basic Salary: " + salary.getBasic());        System.out.println("DA: " + salary.getDa());        System.out.println("HRA: " + salary.getHra());        System.out.println("Total Salary: "                + salary.getTotalSalary());    }}